// Query console: analytical SQL over the published Atlas dataset, run in the
// browser with DuckDB-WASM. The engine and the data load lazily — nothing is
// fetched until this page runs its first query — and DuckDB itself runs in a
// Web Worker, so a slow query never blocks the page.
//
// Data: Parquet tables generated by scripts/build-query-parquet.py (static
// build) or by the async live indexer (scripts/build_live_index.py). Either
// way the page follows the same protocol: fetch latest.json from the index
// base, then the manifest it names, then one Parquet file per table. The
// base is the <meta name="atlas-live-index"> URL when set, otherwise the
// same-origin ./data/query/ directory from the static build. When latest.json
// is absent (an older deploy) the page falls back to manifest.json directly.
// The page creates one DuckDB view per table, then runs the user's SQL
// read-only against those views. Only a single SELECT (or WITH … SELECT)
// statement is accepted; anything else is rejected before it reaches DuckDB.

const DUCKDB_BASE = './vendor/duckdb/';
const QUERY_DIR = './data/query/';
const MAX_DISPLAY_ROWS = 500;

// The live-index base: a public bucket URL from the meta tag, or the static
// build output. Always ends with a slash so relative resolution works.
const INDEX_BASE = (() => {
  const configured = document
    .querySelector('meta[name="atlas-live-index"]')?.content?.trim();
  const base = configured || QUERY_DIR;
  return base.endsWith('/') ? base : `${base}/`;
})();

const EXAMPLES = [
  {
    label: 'Opportunities by kind',
    sql: "SELECT kind, COUNT(*) AS n FROM opportunities GROUP BY kind ORDER BY n DESC",
  },
  {
    label: 'Largest AUD funding rounds',
    sql: "SELECT startup, stage, announced_on, amount FROM funding_rounds WHERE currency = 'AUD' AND amount IS NOT NULL ORDER BY amount DESC LIMIT 10",
  },
  {
    label: 'Startups founded per year',
    sql: "SELECT founded_year, COUNT(*) AS startups FROM startups WHERE founded_year IS NOT NULL GROUP BY founded_year ORDER BY founded_year",
  },
  {
    label: 'Reviewed partners by type',
    sql: "SELECT type, COUNT(*) AS n FROM partners GROUP BY type ORDER BY n DESC",
  },
  {
    label: 'Funding rounds since 2025',
    sql: "SELECT startup, stage, announced_on, amount, currency FROM funding_rounds WHERE announced_on >= '2025-01-01' ORDER BY announced_on DESC LIMIT 20",
  },
  {
    label: 'Partner leads not yet reviewed',
    sql: "SELECT name FROM partner_leads WHERE NOT reviewed ORDER BY name LIMIT 20",
  },
  {
    label: 'Total raised per startup (AUD)',
    sql: "SELECT startup, COUNT(*) AS rounds, SUM(amount) AS total_aud FROM funding_rounds WHERE currency = 'AUD' GROUP BY startup ORDER BY total_aud DESC LIMIT 10",
  },
  {
    label: 'Graph edges by kind',
    sql: "SELECT kind, COUNT(*) AS n FROM edges GROUP BY kind ORDER BY n DESC",
  },
  {
    label: 'Co-investors (shared funding edges)',
    sql: "SELECT a.source AS investor, b.source AS co_investor, a.target AS startup FROM edges a JOIN edges b ON a.target = b.target AND a.kind = b.kind WHERE a.kind IN ('led_round', 'participated_in') AND a.source < b.source ORDER BY startup, investor LIMIT 20",
  },
  {
    label: 'Startups a partner supports',
    sql: "SELECT source AS partner, COUNT(*) AS startups FROM edges WHERE kind = 'supports' GROUP BY source ORDER BY startups DESC LIMIT 10",
  },
];

const statusEl = document.getElementById('query-status');
const provenanceEl = document.getElementById('query-provenance');
const tablesEl = document.getElementById('query-tables');
const examplesEl = document.getElementById('query-examples');
const editorEl = document.getElementById('query-sql');
const runEl = document.getElementById('query-run');
const downloadEl = document.getElementById('query-download');
const resultsEl = document.getElementById('query-results');

let manifest = null;
let manifestDir = null;
let indexVersion = null;
let connectionPromise = null;
let lastResult = null;

function setStatus(text) {
  statusEl.textContent = text;
}

function absoluteUrl(relative) {
  return new URL(relative, document.baseURI).href;
}

async function fetchJson(url) {
  const response = await fetch(url, { cache: 'no-cache' });
  if (!response.ok) {
    throw new Error(`Could not fetch ${url} (HTTP ${response.status}).`);
  }
  return response.json();
}

async function loadManifest() {
  // Follow the pointer: latest.json names the current index version and its
  // manifest. An older deploy has no latest.json; fall back to the manifest
  // in the base directory so the page keeps working until the next build.
  let pointer = null;
  let manifestUrl;
  try {
    pointer = await fetchJson(`${INDEX_BASE}latest.json`);
    manifestUrl = new URL(pointer.manifest, INDEX_BASE).href;
  } catch (error) {
    manifestUrl = `${INDEX_BASE}manifest.json`;
  }
  manifest = await fetchJson(manifestUrl);
  manifestDir = manifestUrl.slice(0, manifestUrl.lastIndexOf('/') + 1);
  indexVersion = pointer?.version ?? manifest.index_version ?? 'static';
  const total = Object.values(manifest.tables).reduce((sum, table) => sum + table.rows, 0);
  const generated = manifest.generated_at ? new Date(manifest.generated_at).toLocaleString() : 'unknown date';
  const revision = manifest.source_revision ? manifest.source_revision.slice(0, 12) : 'unknown revision';
  provenanceEl.textContent = `Index ${indexVersion} · ${Object.keys(manifest.tables).length} tables, ${total.toLocaleString()} rows. Generated ${generated} from ${revision}.`;
  tablesEl.innerHTML = Object.entries(manifest.tables)
    .map(([name, table]) => `<li><button type="button" class="query-table" data-table="${name}">${name}</button><span>${table.rows.toLocaleString()} rows</span><span class="query-columns">${table.columns.join(', ')}</span></li>`)
    .join('');
}

async function startEngineOnce() {
    setStatus('Loading DuckDB engine…');
    const duckdb = await import('./vendor/duckdb/duckdb-browser.mjs');
    const bundles = {
      mvp: {
        mainModule: absoluteUrl(`${DUCKDB_BASE}duckdb-mvp.wasm`),
        mainWorker: absoluteUrl(`${DUCKDB_BASE}duckdb-browser-mvp.worker.js`),
      },
      eh: {
        mainModule: absoluteUrl(`${DUCKDB_BASE}duckdb-eh.wasm`),
        mainWorker: absoluteUrl(`${DUCKDB_BASE}duckdb-browser-eh.worker.js`),
      },
    };
    // selectBundle picks the fastest bundle this browser can run. The coi
    // (threaded) bundle is not offered: it needs cross-origin isolation
    // headers that GitHub Pages does not send.
    const bundle = await duckdb.selectBundle(bundles);
    const worker = new Worker(bundle.mainWorker);
    const logger = new duckdb.ConsoleLogger();
    const db = new duckdb.AsyncDuckDB(logger, worker);
    await db.instantiate(bundle.mainModule, bundle.pthreadWorker);
    const connection = await db.connect();
    setStatus('Loading tables…');
    for (const name of Object.keys(manifest.tables)) {
      // Tables live next to the manifest: ./data/query/ for the static build,
      // v1/<version>/ for the live index.
      const url = new URL(manifest.tables[name].file, manifestDir).href;
      await connection.query(`CREATE VIEW "${name}" AS SELECT * FROM read_parquet('${url.replaceAll("'", "''")}')`);
    }
    setStatus(`Ready — ${Object.keys(manifest.tables).length} tables loaded. Queries run locally in your browser.`);
    runEl.disabled = false;
    return connection;
}

async function openConnection() {
  if (connectionPromise) return connectionPromise;
  connectionPromise = (async () => {
    // Engine start chains several large fetches (module, worker, multi-MB
    // wasm); a single transient failure used to fail the whole init with no
    // retry. Retry the whole start a few times with backoff — each attempt
    // re-runs the import/instantiate sequence from scratch.
    let lastError;
    for (let attempt = 1; attempt <= 3; attempt += 1) {
      try {
        return await startEngineOnce();
      } catch (error) {
        lastError = error;
        if (attempt < 3) {
          setStatus(`Query engine failed to start (attempt ${attempt} of 3) — retrying…`);
          await new Promise((resolve) => setTimeout(resolve, 500 * attempt));
        }
      }
    }
    throw lastError;
  })();
  connectionPromise.catch((error) => {
    connectionPromise = null;
    // Re-enable Run so the user can retry from the page: runQuery calls
    // openConnection() afresh because the failed promise was cleared above.
    runEl.disabled = false;
    setStatus(`Could not start the query engine: ${error.message} Press Run query to try again.`);
  });
  return connectionPromise;
}

const FORBIDDEN = /\b(ATTACH|DETACH|COPY|INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|PRAGMA|CALL|INSTALL|LOAD|EXPORT|IMPORT|VACUUM|CHECKPOINT|TRUNCATE|GRANT|REVOKE)\b/i;

function validateSql(sql) {
  const text = sql.trim().replace(/;\s*$/, '');
  if (!text) throw new Error('Enter a query first.');
  if (text.includes(';')) throw new Error('Run one statement at a time.');
  if (!/^(SELECT|WITH)\b/i.test(text)) {
    throw new Error('Only SELECT (or WITH … SELECT) queries are allowed here.');
  }
  if (FORBIDDEN.test(text)) {
    throw new Error('That statement is not allowed in the query console.');
  }
  return text;
}

function formatValue(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'bigint') return value.toString();
  if (Array.isArray(value)) return value.join(', ');
  if (value instanceof Date) return value.toISOString().slice(0, 10);
  return String(value);
}

function renderResults(result, elapsedMs) {
  const rows = result.toArray().map((row) => Object.fromEntries(
    result.schema.fields.map((field) => [field.name, row[field.name]]),
  ));
  lastResult = { fields: result.schema.fields.map((field) => field.name), rows };
  downloadEl.disabled = rows.length === 0;
  const shown = rows.slice(0, MAX_DISPLAY_ROWS);
  const note = rows.length > MAX_DISPLAY_ROWS
    ? `Showing ${MAX_DISPLAY_ROWS.toLocaleString()} of ${rows.length.toLocaleString()} rows. Narrow the query or download the CSV for the full result.`
    : `${rows.length.toLocaleString()} row${rows.length === 1 ? '' : 's'} in ${elapsedMs.toFixed(0)} ms.`;
  resultsEl.innerHTML = `<p class="query-result-meta">${note}</p>` + (rows.length === 0
    ? '<p class="query-empty">The query ran but returned no rows.</p>'
    : `<div class="query-table-wrap"><table class="query-result-table"><thead><tr>${lastResult.fields.map((field) => `<th scope="col">${field}</th>`).join('')}</tr></thead><tbody>${shown.map((row) => `<tr>${lastResult.fields.map((field) => `<td>${escapeHtml(formatValue(row[field]))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);
}

function escapeHtml(value) {
  return value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;');
}

async function runQuery() {
  let sql;
  try {
    sql = validateSql(editorEl.value);
  } catch (error) {
    setStatus(error.message);
    return;
  }
  runEl.disabled = true;
  setStatus('Running…');
  try {
    const connection = await openConnection();
    const started = performance.now();
    const result = await connection.query(sql);
    renderResults(result, performance.now() - started);
    setStatus(`Done — ${result.numRows.toLocaleString()} row${result.numRows === 1 ? '' : 's'}.`);
  } catch (error) {
    setStatus(`Query failed: ${error.message}`);
  } finally {
    runEl.disabled = false;
  }
}

function downloadCsv() {
  if (!lastResult) return;
  const escape = (value) => `"${String(value ?? '').replaceAll('"', '""')}"`;
  const lines = [
    lastResult.fields.map(escape).join(','),
    ...lastResult.rows.map((row) => lastResult.fields.map((field) => escape(formatValue(row[field]))).join(',')),
  ];
  const blob = new Blob([lines.join('\n')], { type: 'text/csv' });
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = 'startup-atlas-query.csv';
  link.click();
  URL.revokeObjectURL(link.href);
}

function fillExample(sql) {
  editorEl.value = sql;
  editorEl.focus();
  runQuery();
}

examplesEl.innerHTML = EXAMPLES.map((example, index) => `<li><button type="button" class="query-example" data-example="${index}">${example.label}</button></li>`).join('');
examplesEl.addEventListener('click', (event) => {
  const button = event.target.closest('[data-example]');
  if (button) fillExample(EXAMPLES[Number(button.dataset.example)].sql);
});
tablesEl.addEventListener('click', (event) => {
  const button = event.target.closest('[data-table]');
  if (!button) return;
  editorEl.value = `SELECT * FROM ${button.dataset.table} LIMIT 20`;
  editorEl.focus();
  runQuery();
});
runEl.addEventListener('click', runQuery);
downloadEl.addEventListener('click', downloadCsv);
editorEl.addEventListener('keydown', (event) => {
  if ((event.metaKey || event.ctrlKey) && event.key === 'Enter') {
    event.preventDefault();
    runQuery();
  }
});

const sharedSql = new URLSearchParams(location.search).get('sql');
if (sharedSql) editorEl.value = sharedSql;
// Seed the editor with the first example — the SQL the placeholder
// advertises. Without a real value, clicking Run with the placeholder
// showing hit the "Enter a query first." check even though SQL was visible.
else editorEl.value = EXAMPLES[0].sql;

let datasetReady = false;
loadManifest()
  .then(() => {
    datasetReady = true;
    setStatus('Dataset ready. Starting the query engine…');
    return openConnection();
  })
  .then(() => {
    if (sharedSql) runQuery();
  })
  .catch((error) => {
    // Engine-start failures already set their own status in openConnection;
    // only a manifest failure is a dataset problem.
    if (!datasetReady) setStatus(`Could not load the query dataset: ${error.message}`);
  });
